class Rekening {
  final String pemilik;
  int saldo;
  Rekening(this.pemilik, this.saldo);

  void setor(int jumlah) {
    saldo += jumlah;
    print('$pemilik setor $jumlah, saldo $saldo');
  }

  void tarik(int jumlah) {
    if (jumlah > saldo) {
      print('$pemilik gagal tarik $jumlah, saldo tidak cukup');
      return;
    }
    saldo -= jumlah;
    print('$pemilik tarik $jumlah, saldo $saldo');
  }
}

