class Siswa {
  final String nama;
  final List<int> nilai;
  const Siswa(this.nama, this.nilai);

  double get rataRata => nilai.fold(0, (a, b) => a + b) / nilai.length;
  String get predikat => rataRata >= 85 ? 'A' : rataRata >= 75 ? 'B' : 'C';

  @override
  String toString() => '$nama: ${rataRata.toStringAsFixed(1)} ($predikat)';
}

