class Suhu {
  final String kota;
  final double celsius;
  Suhu(this.kota, this.celsius);

  // dari sensor yang mengirim Fahrenheit
  Suhu.dariFahrenheit(this.kota, double f) : celsius = (f - 32) * 5 / 9;

